    # Handle empty grid or rows
    if not grid:
        return 0
    m = len(grid)
    visited = set()
    def is_land(i, j):
        try:
            val = grid[i][j]
        except Exception:
            return False
        # Accept int 1 or string '1'
        return val == 1 or val == '1'
    def bfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            if not is_land(x, y):
                continue
            visited.add((x, y))
            # explore neighbors
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                # check bounds for row nx
                if 0 <= nx < m:
                    # ensure column index within that row length
                    if 0 <= ny < len(grid[nx]):
                        if (nx, ny) not in visited and is_land(nx, ny):
                            stack.append((nx, ny))
    count = 0
    for i in range(m):
        row_len = len(grid[i])
        for j in range(row_len):
            if is_land(i, j) and (i, j) not in visited:
                bfs(i, j)
                count += 1
    return count

